adcs_vec3_t u, par, perp;
double req_norm, dot, frac;
adcs_status_t st;

if ((request == NULL) || (field == NULL) || (parallel == NULL) ||
    (perpendicular == NULL) || (fraction == NULL)) {
    if (parallel != NULL) *parallel = (adcs_vec3_t){0, 0, 0};
    if (perpendicular != NULL) *perpendicular = (adcs_vec3_t){0, 0, 0};
    if (fraction != NULL) *fraction = 0.0;
    return ADCS_E_NULL;
}

*parallel = (adcs_vec3_t){0, 0, 0};
*perpendicular = (adcs_vec3_t){0, 0, 0};
*fraction = 0.0;

if ((!adcs_is_finite_vec3(request)) || (!adcs_is_finite_vec3(field))) {
    return ADCS_E_DEGENERATE;
}

st = adcs_vec3_normalize(field, ADCS_EPS_NORM, &u);
if (st != ADCS_OK) {
    return ADCS_E_DEGENERATE;
}

req_norm = adcs_vec3_norm(request);

dot = adcs_vec3_dot(request, &u);
par = adcs_vec3_scale(&u, dot);
perp = adcs_vec3_sub(request, &par);

*parallel = par;
*perpendicular = perp;

if (req_norm == 0.0) {
    frac = 0.0;
} else {
    frac = adcs_vec3_norm(&perp) / req_norm;
}
*fraction = frac;

return ADCS_OK;

